// Install Confidence score writer. final_score is the 0–10 IC (NULL when 'wait').
// `state` carries the install status: 'wait' | 'skip-cve' | 'skip-hotfix' | 'eligible'.
// risk_index / fix_bonus are legacy columns from the old model — left untouched here.
const updateScoreStmt = db.prepare(`
UPDATE releases SET final_score=:final_score,
  negative_issues=:negative_issues, positive_issues=:positive_issues,
  state=:state, recommended=:recommended, score_reason=:score_reason,
  broken_surfaces=:broken_surfaces,
  closed_serious_fixed=:closed_serious_fixed,
  opened_serious_during_reign=:opened_serious_during_reign,
  scored_at=:scored_at
WHERE tag=:tag
`);
const releaseScoreTargetStmt = db.prepare(`
SELECT tag, prerelease, catalog_active
FROM releases
WHERE tag=?
`);

function assertActiveStableReleaseScoreTarget(tag: string): void {
  const release = releaseScoreTargetStmt.get(tag) as {
    tag: string;
    prerelease: number;
    catalog_active: number;
  } | undefined;
  if (!release) {
    throw new Error(`Cannot persist score for missing release ${tag}`);
  }
  if (release.catalog_active !== 1) {
    throw new Error(`Cannot persist score for inactive release ${tag}`);
  }
  if (release.prerelease !== 0) {
    throw new Error(`Cannot persist score for prerelease ${tag}`);
  }
}

export function updateReleaseScore(args: {
  tag: string;
  final_score: number | null;
  negative_issues: number;
  positive_issues: number;
  state: string;
  recommended: number;
  score_reason: string;
  broken_surfaces: string;
  closed_serious_fixed: number;
  opened_serious_during_reign: number;
  scored_at?: string;
}): void {
  assertActiveStableReleaseScoreTarget(args.tag);
  updateScoreStmt.run({ ...args, scored_at: args.scored_at ?? new Date().toISOString() });
}

const clearReleaseScoresOutsideTagsStmt = db.prepare(`
UPDATE releases
SET final_score=NULL,
    negative_issues=NULL,
    positive_issues=NULL,
    scored_at=NULL,
    state=NULL,
    closed_serious_fixed=0,
    opened_serious_during_reign=0,
    recommended=0,
    score_reason=NULL,
    broken_surfaces=NULL
WHERE tag NOT IN (SELECT value FROM json_each(?))
  AND (
    final_score IS NOT NULL
    OR scored_at IS NOT NULL
    OR state IS NOT NULL
    OR recommended != 0
    OR score_reason IS NOT NULL
  )
`);
const deleteReleaseScoreAuditsOutsideTagsStmt = dbReadOnly ? null : db.prepare(`
DELETE FROM release_score_audits
WHERE release_tag NOT IN (SELECT value FROM json_each(?))
`);

export function clearReleaseScoresOutsideTags(tags: string[]): { releaseRows: number; auditRows: number } {
  if (!deleteReleaseScoreAuditsOutsideTagsStmt) {
    throw new Error('Release score pruning is unavailable while the database is read-only');
  }
  if (!tags.length) throw new Error('Refusing to clear scored releases without a non-empty retained tag set');
  const retained = JSON.stringify([...new Set(tags)]);
  const releaseResult = clearReleaseScoresOutsideTagsStmt.run(retained);
  const auditResult = deleteReleaseScoreAuditsOutsideTagsStmt.run(retained);
  return {
    releaseRows: Number(releaseResult.changes ?? 0),
    auditRows: Number(auditResult.changes ?? 0),
  };
}

